import{_ as r,o as t,c as a,a0 as i}from"./chunks/framework.DScjKhBS.js";const h=JSON.parse('{"title":"Sources and evidence map","description":"Internal project evidence and external sources used to build this microsite.","frontmatter":{"title":"Sources and evidence map","description":"Internal project evidence and external sources used to build this microsite."},"headers":[],"relativePath":"reports/pr-review-continuity/07-sources-and-evidence-map.md","filePath":"reports/pr-review-continuity/07-sources-and-evidence-map.md"}'),n={name:"reports/pr-review-continuity/07-sources-and-evidence-map.md"};function o(s,e,l,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="sources-and-evidence-map" tabindex="-1">Sources and evidence map <a class="header-anchor" href="#sources-and-evidence-map" aria-label="Permalink to &quot;Sources and evidence map&quot;">​</a></h1><h2 id="internal-project-research-this-repository" tabindex="-1">Internal project research (this repository) <a class="header-anchor" href="#internal-project-research-this-repository" aria-label="Permalink to &quot;Internal project research (this repository)&quot;">​</a></h2><ul><li><a href="./reports/ai-augmented-dev-pipeline/02-pr-review.html">AI-Augmented Development Pipelines — PR Review</a><br> First-pass AI review framing, merge guardrails, failure modes, and KPI logic.</li><li><a href="./reports/ai-augmented-dev-pipeline/01-overview.html">AI-Augmented Development Pipelines — Overview</a><br> Human-in-control operating posture for AI in development workflows.</li><li><a href="./reports/ai-augmented-dev-pipeline/08-governance-and-controls.html">AI-Augmented Development Pipelines — Governance and Controls</a><br> Data, policy, and transparency controls.</li><li><a href="./reports/dark-factory/10-adopting-the-shift.html">Dark Factories — Adopting the Shift</a><br> Outcome-based validation in addition to diff-level review.</li><li><a href="./reports/ai-wp-laravel-pipeline/01-research-document.html">AI in the WordPress + Laravel Pipeline</a><br> Review bottleneck context, pilot structure, and risks.</li></ul><hr><h2 id="external-guidance-and-evidence" tabindex="-1">External guidance and evidence <a class="header-anchor" href="#external-guidance-and-evidence" aria-label="Permalink to &quot;External guidance and evidence&quot;">​</a></h2><h3 id="review-process-standards" tabindex="-1">Review process standards <a class="header-anchor" href="#review-process-standards" aria-label="Permalink to &quot;Review process standards&quot;">​</a></h3><ul><li>Google Engineering Practices — <strong>The Standard of Code Review</strong><br><a href="https://google.github.io/eng-practices/review/reviewer/standard.html" target="_blank" rel="noreferrer">https://google.github.io/eng-practices/review/reviewer/standard.html</a></li><li>Google Engineering Practices — <strong>What to look for in code review</strong><br><a href="https://google.github.io/eng-practices/review/reviewer/looking-for.html" target="_blank" rel="noreferrer">https://google.github.io/eng-practices/review/reviewer/looking-for.html</a></li><li>GitHub Docs — <strong>Best practices for pull requests</strong><br><a href="https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/getting-started/best-practices-for-pull-requests" target="_blank" rel="noreferrer">https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/getting-started/best-practices-for-pull-requests</a></li></ul><h3 id="review-capacity-and-quality-evidence" tabindex="-1">Review capacity and quality evidence <a class="header-anchor" href="#review-capacity-and-quality-evidence" aria-label="Permalink to &quot;Review capacity and quality evidence&quot;">​</a></h3><ul><li>SmartBear — <strong>Best Practices for Code Review</strong> (includes Cisco study guidance on LOC/timebox)<br><a href="https://smartbear.com/en/learn/code-review/best-practices-for-peer-code-review/" target="_blank" rel="noreferrer">https://smartbear.com/en/learn/code-review/best-practices-for-peer-code-review/</a></li><li>Avelino et al. — <strong>A Novel Approach for Estimating Truck Factors</strong> (knowledge concentration risk)<br><a href="https://arxiv.org/abs/1604.06766" target="_blank" rel="noreferrer">https://arxiv.org/abs/1604.06766</a></li></ul><h3 id="ai-assisted-coding-and-review-risk" tabindex="-1">AI-assisted coding and review risk <a class="header-anchor" href="#ai-assisted-coding-and-review-risk" aria-label="Permalink to &quot;AI-assisted coding and review risk&quot;">​</a></h3><ul><li>Catalan et al. (2026) — <strong>&quot;I&#39;m Not Reading All of That&quot;</strong> (cognitive engagement decline with agentic assistants; formative study)<br><a href="https://arxiv.org/abs/2603.14225" target="_blank" rel="noreferrer">https://arxiv.org/abs/2603.14225</a></li><li>GitClear — <strong>Coding on Copilot</strong> (maintainability/churn trend analysis; industry dataset)<br><a href="https://www.gitclear.com/coding_on_copilot_data_shows_ais_downward_pressure_on_code_quality" target="_blank" rel="noreferrer">https://www.gitclear.com/coding_on_copilot_data_shows_ais_downward_pressure_on_code_quality</a></li></ul><h3 id="secure-development-governance" tabindex="-1">Secure development governance <a class="header-anchor" href="#secure-development-governance" aria-label="Permalink to &quot;Secure development governance&quot;">​</a></h3><ul><li>NIST SP 800-218 — <strong>Secure Software Development Framework (SSDF) v1.1</strong><br><a href="https://doi.org/10.6028/NIST.SP.800-218" target="_blank" rel="noreferrer">https://doi.org/10.6028/NIST.SP.800-218</a></li></ul><hr><h2 id="evidence-quality-notes" tabindex="-1">Evidence quality notes <a class="header-anchor" href="#evidence-quality-notes" aria-label="Permalink to &quot;Evidence quality notes&quot;">​</a></h2><ul><li>Some AI-assistance findings are recent and include preprint/formative studies; treat exact percentages cautiously, but the operational risk pattern is directionally consistent.</li><li>Industry benchmarks are most useful when normalized to your own baseline and repository mix.</li><li>Governance recommendations should be adapted to client data sensitivity and contractual requirements.</li></ul><hr><p><strong>Previous:</strong> <a href="./reports/pr-review-continuity/06-30-60-90-rollout.html">30-60-90 day rollout</a></p>',18)])])}const g=r(n,[["render",o]]);export{h as __pageData,g as default};
